import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("as of roles", () => {
  test("as of roles", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setToday(pg_uma, "2026-03-05");
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    expect(await ui.setRole(pg_uma, "vic", "clerk")).toBe(true);
    await ui.setToday(pg_uma, "2026-03-10");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("role-row-vic").getByTestId("role-value")).toHaveText("clerk");
    await expect(pg_uma.getByTestId("role-row-wes").getByTestId("role-value")).toHaveText("viewer");
    await ui.setAsOf(pg_uma, "2026-03-01");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("role-row-vic").getByTestId("role-value")).toHaveText("steward");
    await ui.setAsOf(pg_uma, "2026-03-05");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("role-row-vic").getByTestId("role-value")).toHaveText("clerk");
    await expect(pg_uma.getByTestId("role-row-wes").getByTestId("role-value")).toHaveText("viewer");
    await ui.clearAsOf(pg_uma);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("role-row-vic").getByTestId("role-value")).toHaveText("clerk");
    await expect(pg_uma.getByTestId("role-row-wes").getByTestId("role-value")).toHaveText("viewer");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=wes role=viewer`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=clerk`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`
    ]);
  });
  test("as of roles scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "3.00");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
    await ui.setSetting(pg_uma, "grace-A", "2");
    expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    await ui.setSetting(pg_uma, "fiscal-start-month", "7");
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-10", "half-even")).toBe(true);
    await ui.setSetting(pg_uma, "review-sla", "1");
    await ui.setSetting(pg_uma, "clerk-limit-C", "0.50");
    await ui.setSetting(pg_uma, "max-open", "1");
    await ui.setSetting(pg_uma, "pending-sla", "1");
    expect(await ui.setRole(pg_uma, "vic", "restricted")).toBe(true);
    await ui.setSetting(pg_uma, "perm-today", "clerk");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": " Ada@x "}));
    expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "contact": " Ada@x "})).toBeNull();
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "20", "tags": "a"}));
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "33.33", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
    expect(await ui.addPool(pg_uma, "P2")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Ada", "share": "100.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
    const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "3.33", "start": "2026-03-01", "end": "2026-04-30", "every": "10"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "0.40", "ref": "inv 7"}));
    const c_cam_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "0.40"}, p_cam));
    expect(await ui.statementAsOf(pg_uma, p_ada, "2026-02-10")).toBe(false);
    expect(await ui.importOpenings(pg_uma, "Cam,P2,x")).toBeNull();
    expect(await ui.retire(pg_uma, p_cam, "2026-03-20")).toBe(true);
    await ui.showRetired(pg_uma, true);
